WITH base AS (SELECT * FROM stores WHERE city != 'New York' AND MONTH(opened_date) IN (3, 9, 12) AND sqft = 6577), city_summary AS (SELECT city, DATE_TRUNC('MONTH', opened_date) AS opened_month, ROUND((100 * SUM(CASE WHEN city = 'New York' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_new_york, MAX(sqft) - MIN(sqft) AS sqft_range FROM base GROUP BY city, DATE_TRUNC('MONTH', opened_date)) SELECT city, opened_month, sqft_range FROM city_summary
